#include "stdlib/lapack/base/dgttrf.h"
#include <stdio.h>

int main( void ) {
	double DL[] = { 3.0, 1.0 };
	double D[] = { 1.0, 4.0, 5.0 };
	double DU[] = { 2.0, 1.0 };
	double DU2[ 1 ];
	LAPACK_INT IPIV[ 3 ];
	LAPACK_INT info;
	LAPACK_INT i;

	info = API_SUFFIX(c_dgttrf)( 3, DL, D, DU, DU2, IPIV );
	printf( "status: %" LAPACK_IFMT "\n", info );
	for ( i = 0; i < 3; i++ ) {
		printf( "D[%" LAPACK_IFMT "]: %g; pivot: %" LAPACK_IFMT "\n", i, D[ i ], IPIV[ i ] );
	}
	return info != 0;
}
